package attackdefense

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os/exec"
	"regexp"
	"strings"
	"syscall"
	"time"

	"github.com/google/uuid"
)

// CheckerVulnerability is the server-owned test selection passed to the trusted
// checker image. Selectors are never returned to participants.
type CheckerVulnerability struct {
	Key             string
	ExploitSelector string
	PatchSelector   string
}

// CheckRequest is the bounded checker input. Image is validated against the
// server allowlist; directory paths are generated by the worker.
type CheckRequest struct {
	RunID           uuid.UUID
	Kind            string
	Image           string
	SourceDir       string
	ExploitDir      string
	Vulnerabilities []CheckerVulnerability
	Timeout         time.Duration
}

// CheckResult is the sanitized checker outcome.
type CheckResult struct {
	Verdict   Verdict
	Logs      []string
	Truncated bool
}

// Verdict is the only accepted checker JSON shape.
type Verdict struct {
	Vulnerabilities []VerdictVulnerability `json:"vulnerabilities"`
}

// VerdictVulnerability reports one configured vulnerability. PATCH awards
// require both SecurityFixed and RegressionPassed.
type VerdictVulnerability struct {
	Key              string         `json:"key"`
	Status           string         `json:"status"`
	SecurityFixed    *bool          `json:"securityFixed,omitempty"`
	RegressionPassed *bool          `json:"regressionPassed,omitempty"`
	SecurityTests    map[string]int `json:"securityTests,omitempty"`
	RegressionTests  map[string]int `json:"regressionTests,omitempty"`
	Message          string         `json:"message,omitempty"`
}

// Checker executes untrusted participant code only inside the isolated checker
// container. The worker never executes repository code on the host.
type Checker interface {
	Check(ctx context.Context, req CheckRequest) (CheckResult, error)
}

// CheckerConfig holds the operator-pinned Docker isolation policy. There is no
// student-selectable command, image, path, network or capability.
type CheckerConfig struct {
	DockerBinary   string
	ImageAllowlist []string
	CPUs           string
	Memory         string
	PIDs           int
	TmpfsSize      string
	MaxOutputBytes int64
}

// DockerChecker is the real Docker CLI checker.
type DockerChecker struct {
	config CheckerConfig
}

// NewDockerChecker constructs the checker. An empty allowlist is accepted at
// construction but every Check fails closed with ErrRunnerUnavailable.
func NewDockerChecker(cfg CheckerConfig) (*DockerChecker, error) {
	if strings.TrimSpace(cfg.DockerBinary) == "" {
		cfg.DockerBinary = "docker"
	}
	if cfg.CPUs == "" {
		cfg.CPUs = "1"
	}
	if cfg.Memory == "" {
		cfg.Memory = "512m"
	}
	if cfg.PIDs <= 0 {
		cfg.PIDs = 128
	}
	if cfg.TmpfsSize == "" {
		cfg.TmpfsSize = "64m"
	}
	if cfg.MaxOutputBytes <= 0 {
		cfg.MaxOutputBytes = 1 << 20
	}
	return &DockerChecker{config: cfg}, nil
}

var (
	dockerImageDigestPattern = regexp.MustCompile(`^[a-z0-9][a-z0-9._-]*(?::[0-9]+)?(?:/[a-z0-9][a-z0-9._-]*)+@sha256:[a-f0-9]{64}$`)
	secretLikePattern        = regexp.MustCompile(`(?i)(token|secret|password|authorization)(\s*[:=]\s*)([^\s,;]+)`)
)

// ValidateRunnerImage enforces a digest-pinned image and exact allowlist
// membership. Mutable tags are rejected even if an operator lists them.
func (c *DockerChecker) ValidateRunnerImage(image string) error {
	image = strings.TrimSpace(image)
	if image == "" || !dockerImageDigestPattern.MatchString(image) {
		return Invalid("runnerImage", "must be an immutable sha256 digest reference", "INVALID_FORMAT")
	}
	for _, allowed := range c.config.ImageAllowlist {
		if strings.TrimSpace(allowed) == image {
			return nil
		}
	}
	return ErrRunnerUnavailable
}

// Check runs the trusted image with no network, no host socket, dropped
// capabilities, a read-only rootfs, bounded resources and read-only sanitized
// checkouts as the only mounts.
func (c *DockerChecker) Check(ctx context.Context, req CheckRequest) (CheckResult, error) {
	if c == nil {
		return CheckResult{}, ErrNoChecker
	}
	if err := c.ValidateRunnerImage(req.Image); err != nil {
		return CheckResult{}, err
	}
	if req.Kind != RunKindExploit && req.Kind != RunKindPatch {
		return CheckResult{}, ErrInvalidVerdict
	}
	if !safeMountPath(req.SourceDir) || !safeMountPath(req.ExploitDir) {
		return CheckResult{}, ErrCheckerFailed
	}
	if req.Timeout <= 0 || req.Timeout > time.Hour {
		req.Timeout = 10 * time.Minute
	}
	name := containerName(req.RunID)
	args := c.containerArgs(req, name)

	runCtx, cancel := context.WithTimeout(ctx, req.Timeout)
	defer cancel()
	stdout := &boundedBuffer{limit: c.config.MaxOutputBytes}
	stderr := &boundedBuffer{limit: c.config.MaxOutputBytes}
	command := exec.CommandContext(runCtx, c.config.DockerBinary, args...)
	command.Stdout = stdout
	command.Stderr = stderr
	command.Env = []string{
		"PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin",
		"HOME=/tmp",
	}
	command.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	err := command.Run()
	if runCtx.Err() == context.DeadlineExceeded {
		c.forceRemove(name)
		return CheckResult{}, fmt.Errorf("%w: checker timed out", ErrCheckerFailed)
	}
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return CheckResult{}, fmt.Errorf("%w: checker exited nonzero", ErrCheckerFailed)
		}
		return CheckResult{}, fmt.Errorf("%w: checker could not start", ErrCheckerFailed)
	}

	verdictRaw, logs, verdictCount := extractVerdict(stdout.Bytes())
	logs = append(logs, sanitizeLogLines(splitLines(stderr.Bytes()), req.Vulnerabilities)...)
	logs = sanitizeLogLines(logs, req.Vulnerabilities)
	if verdictCount != 1 {
		return CheckResult{Verdict: Verdict{}, Logs: logs, Truncated: stdout.Truncated() || stderr.Truncated()}, fmt.Errorf("%w: exactly one verdict line required", ErrInvalidVerdict)
	}
	verdict, err := ParseVerdict(verdictRaw, req.Vulnerabilities)
	if err != nil {
		return CheckResult{Verdict: Verdict{}, Logs: logs, Truncated: stdout.Truncated() || stderr.Truncated()}, err
	}
	return CheckResult{
		Verdict:   verdict,
		Logs:      logs,
		Truncated: stdout.Truncated() || stderr.Truncated() || len(logs) >= MaxCheckerLogLines,
	}, nil
}

func containerName(runID uuid.UUID) string {
	return "actfb-ad-" + strings.ReplaceAll(runID.String(), "-", "")[:24]
}

// containerArgs is the exact, testable isolation command. Only the two
// read-only sanitized checkouts are mount sources; no host path, socket,
// credential, database or NATS environment is present.
func (c *DockerChecker) containerArgs(req CheckRequest, name string) []string {
	args := []string{
		"run", "--rm", "--name", name,
		"--network", "none",
		"--read-only",
		"--tmpfs", "/tmp:rw,noexec,nosuid,nodev,size=" + c.config.TmpfsSize,
		"--cap-drop", "ALL",
		"--security-opt", "no-new-privileges",
		"--pids-limit", fmt.Sprintf("%d", c.config.PIDs),
		"--memory", c.config.Memory,
		"--cpus", c.config.CPUs,
		"--user", "65534:65534",
		"--workdir", "/work",
		"--mount", "type=bind,source=" + req.SourceDir + ",target=/source,readonly",
		"--mount", "type=bind,source=" + req.ExploitDir + ",target=/exploit,readonly",
		"--env", "ACTFB_RUN_KIND=" + req.Kind,
		"--env", "ACTFB_RUN_ID=" + req.RunID.String(),
		"--env", "ACTFB_TIMEOUT_SECONDS=" + fmt.Sprintf("%d", int(req.Timeout.Seconds())),
		"--env", "HOME=/tmp",
		req.Image,
		"--run-kind", req.Kind,
		"--source", "/source",
		"--exploit", "/exploit",
	}
	for _, vulnerability := range req.Vulnerabilities {
		args = append(args, "--selector", vulnerability.Key+"="+vulnerability.ExploitSelector+"|"+vulnerability.PatchSelector)
	}
	return args
}

func (c *DockerChecker) forceRemove(name string) {
	cleanupCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = exec.CommandContext(cleanupCtx, c.config.DockerBinary, "rm", "-f", name).Run()
}

func safeMountPath(path string) bool {
	if path == "" || strings.ContainsAny(path, ",\n\r\x00\"'") {
		return false
	}
	return strings.HasPrefix(path, "/")
}

const verdictPrefix = "ACTFB_VERDICT:"

func extractVerdict(stdout []byte) ([]byte, []string, int) {
	lines := splitLines(stdout)
	logs := make([]string, 0, len(lines))
	var verdict []byte
	count := 0
	for _, line := range lines {
		// Only the harness line may start with the marker. Child output is
		// escaped with a leading space by the example harness; never TrimSpace
		// before this check or a spoofed log line would count as a verdict.
		if strings.HasPrefix(line, verdictPrefix) {
			count++
			if len(verdict) == 0 && len(line) <= MaxCheckerOutput {
				verdict = []byte(strings.TrimSpace(strings.TrimPrefix(line, verdictPrefix)))
			}
			continue
		}
		logs = append(logs, line)
	}
	return verdict, logs, count
}

func splitLines(data []byte) []string {
	raw := strings.ReplaceAll(string(data), "\r\n", "\n")
	raw = strings.TrimRight(raw, "\n")
	if raw == "" {
		return nil
	}
	return strings.Split(raw, "\n")
}

// ParseVerdict strictly validates the untrusted checker JSON. Unknown keys,
// duplicate keys, unknown vulnerability keys, unbounded counters and hidden
// selector echoes are rejected.
func ParseVerdict(raw []byte, expected []CheckerVulnerability) (Verdict, error) {
	if len(raw) == 0 || len(raw) > MaxCheckerOutput {
		return Verdict{}, ErrInvalidVerdict
	}
	allowed := make(map[string]CheckerVulnerability, len(expected))
	selectors := make([]string, 0, len(expected)*2)
	for _, item := range expected {
		allowed[item.Key] = item
		if item.ExploitSelector != "" {
			selectors = append(selectors, item.ExploitSelector)
		}
		if item.PatchSelector != "" {
			selectors = append(selectors, item.PatchSelector)
		}
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	var verdict Verdict
	if err := decoder.Decode(&verdict); err != nil {
		return Verdict{}, ErrInvalidVerdict
	}
	var trailing any
	if err := decoder.Decode(&trailing); err != io.EOF {
		return Verdict{}, ErrInvalidVerdict
	}
	if len(verdict.Vulnerabilities) > MaxVulnerabilities {
		return Verdict{}, ErrInvalidVerdict
	}
	seen := make(map[string]struct{}, len(verdict.Vulnerabilities))
	for index := range verdict.Vulnerabilities {
		item := &verdict.Vulnerabilities[index]
		if _, ok := allowed[item.Key]; !ok {
			return Verdict{}, ErrInvalidVerdict
		}
		if _, exists := seen[item.Key]; exists {
			return Verdict{}, ErrInvalidVerdict
		}
		seen[item.Key] = struct{}{}
		switch item.Status {
		case ResultStatusPassed, ResultStatusFailed, ResultStatusError, ResultStatusSkipped:
		default:
			return Verdict{}, ErrInvalidVerdict
		}
		if !validCounters(item.SecurityTests) || !validCounters(item.RegressionTests) {
			return Verdict{}, ErrInvalidVerdict
		}
		item.Message = redactText(trimTo(item.Message, MaxVerdictMessage), selectors)
	}
	return verdict, nil
}

func validCounters(counters map[string]int) bool {
	if len(counters) > 64 {
		return false
	}
	for key, value := range counters {
		if key == "" || len(key) > 128 || value < 0 || value > 1_000_000 {
			return false
		}
	}
	return true
}

func sanitizeLogLines(lines []string, vulnerabilities []CheckerVulnerability) []string {
	selectors := make([]string, 0, len(vulnerabilities)*2)
	for _, vulnerability := range vulnerabilities {
		if vulnerability.ExploitSelector != "" {
			selectors = append(selectors, vulnerability.ExploitSelector)
		}
		if vulnerability.PatchSelector != "" {
			selectors = append(selectors, vulnerability.PatchSelector)
		}
	}
	sanitized := make([]string, 0, len(lines))
	for _, line := range lines {
		if len(line) == 0 {
			continue
		}
		sanitized = append(sanitized, redactText(trimTo(line, MaxCheckerLogLine), selectors))
		if len(sanitized) >= MaxCheckerLogLines {
			break
		}
	}
	return sanitized
}

func redactText(line string, selectors []string) string {
	for _, selector := range selectors {
		if len(selector) >= 4 {
			line = strings.ReplaceAll(line, selector, "[redacted-selector]")
		}
	}
	return secretLikePattern.ReplaceAllString(line, "$1$2[redacted]")
}

type boundedBuffer struct {
	data      bytes.Buffer
	limit     int64
	truncated bool
}

func (b *boundedBuffer) Write(p []byte) (int, error) {
	remaining := b.limit - int64(b.data.Len())
	if remaining <= 0 {
		b.truncated = true
		return len(p), nil
	}
	if int64(len(p)) > remaining {
		_, _ = b.data.Write(p[:remaining])
		b.truncated = true
		return len(p), nil
	}
	_, _ = b.data.Write(p)
	return len(p), nil
}

func (b *boundedBuffer) Bytes() []byte   { return b.data.Bytes() }
func (b *boundedBuffer) Truncated() bool { return b.truncated }
